draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // roads
  ctx.beginPath();
  ctx.moveTo(0, H/2);
  ctx.lineTo(W, H/2);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, 0);
  ctx.lineTo(W/2, H);
  ctx.stroke();

  // buildings
  ctx.fillStyle = 'black';
  ctx.fillRect(50, 50, 50, 100);
  ctx.fillRect(W-100, 50, 50, 100);
  ctx.fillRect(50, H-150, 50, 100);
  ctx.fillRect(W-100, H-150, 50, 100);

  // cars
  ctx.fillStyle = 'black';
  ctx.save();
  ctx.translate(W/2 + Math.sin(t)*100, H/2);
  ctx.beginPath();
  ctx.rect(-10, -5, 20, 10);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(W/2 + Math.cos(t)*100, H/2 + Math.sin(t)*50);
  ctx.beginPath();
  ctx.rect(-10, -5, 20, 10);
  ctx.fill();
  ctx.restore();

  // trees
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(100, H-50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W-100, H-50, 20, 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
